import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    records = []

    try:
        for record in reader:
            records.append([value for value in record])
    except csv.Error:
        pass

    def nonempty_count(row):
        return sum(bool(value.strip()) for value in row)

    def looks_like_data(value):
        value = value.strip()
        return bool(
            re.match(r"^\d{1,4}[/-]\d{1,2}[/-]\d{1,4}$", value)
            or re.match(r"^[£$€]\s*[\d,.]+$", value)
            or re.match(r"^-?[\d,.]+$", value)
        )

    header_index = None
    for index, row in enumerate(records):
        if nonempty_count(row) < 3:
            continue
        first_value = next((value.strip() for value in row if value.strip()), "")
        if first_value and not looks_like_data(first_value):
            header_index = index
            break

    if header_index is None:
        width = max([9] + [len(row) for row in records])
        columns = [f"Column {index + 1}" for index in range(width)]
        return {
            "columns": columns,
            "rows": [row + [""] * (width - len(row)) for row in records],
        }

    top = records[header_index][:]
    width = max(9, len(top))
    top += [""] * (width - len(top))

    second_index = None
    for index in range(header_index + 1, len(records)):
        row = records[index]
        if not nonempty_count(row):
            continue
        values = [value.strip() for value in row if value.strip()]
        if values and all(not looks_like_data(value) for value in values):
            second_index = index
        break

    bottom = [""] * width
    data_start = header_index + 1
    if second_index is not None:
        bottom = records[second_index][:width]
        bottom += [""] * (width - len(bottom))
        data_start = second_index + 1

    columns = []
    for index in range(width):
        upper = top[index].strip()
        lower = bottom[index].strip()

        if upper and lower:
            columns.append(f"{upper} - {lower}")
        elif lower:
            columns.append(lower)
        elif upper:
            columns.append(upper)
        else:
            columns.append(f"Column {index + 1}")

    rows = []
    for row in records[data_start:]:
        row = row[:]
        if len(row) > width:
            width = len(row)
            columns.extend(f"Column {index + 1}" for index in range(len(columns), width))
            rows = [existing + [""] * (width - len(existing)) for existing in rows]
        rows.append(row + [""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
